"""==============================================================================IOTEC105_AGENT_REGISTRY_ENGINE.py==============================================================================Registro Oficial de Agentes do IOTECVersão: 1.0=============================================================================="""from __future__ import annotationsimport jsonimport sqlite3from pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class AgentRegistry:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row        self.create_table()    # ---------------------------------------------------------------------    def create_table(self):        self.conn.execute("""        CREATE TABLE IF NOT EXISTS agent_registry(            agent_uuid TEXT PRIMARY KEY,            agent_name TEXT NOT NULL,            role TEXT,            version TEXT,            status TEXT,            endpoint TEXT,            capabilities TEXT,            permissions TEXT,            heartbeat TEXT,            created_at TEXT,            updated_at TEXT        )        """)        self.conn.commit()    # ---------------------------------------------------------------------    def register(            self,            agent_uuid,            agent_name,            role,            version="1.0",            status="ONLINE",            endpoint="LOCAL",            capabilities=None,            permissions=None    ):        now = datetime.utcnow().isoformat()        self.conn.execute("""        INSERT OR REPLACE INTO agent_registry(            agent_uuid,            agent_name,            role,            version,            status,            endpoint,            capabilities,            permissions,            heartbeat,            created_at,            updated_at        )        VALUES(?,?,?,?,?,?,?,?,?,?,?)        """,        (            agent_uuid,            agent_name,            role,            version,            status,            endpoint,            json.dumps(capabilities or []),            json.dumps(permissions or []),            now,            now,            now        ))        self.conn.commit()    # ---------------------------------------------------------------------    def heartbeat(self, agent_uuid):        now = datetime.utcnow().isoformat()        self.conn.execute("""        UPDATE agent_registry        SET heartbeat=?,            updated_at=?        WHERE agent_uuid=?        """,(now, now, agent_uuid))        self.conn.commit()    # ---------------------------------------------------------------------    def set_status(self, agent_uuid, status):        self.conn.execute("""        UPDATE agent_registry        SET status=?,            updated_at=?        WHERE agent_uuid=?        """,(status, datetime.utcnow().isoformat(), agent_uuid))        self.conn.commit()    # ---------------------------------------------------------------------    def list_agents(self):        rows = self.conn.execute("""        SELECT *        FROM agent_registry        ORDER BY agent_name        """).fetchall()        return [dict(r) for r in rows]    # ---------------------------------------------------------------------    def get(self, agent_uuid):        row = self.conn.execute("""        SELECT *        FROM agent_registry        WHERE agent_uuid=?        """,(agent_uuid,)).fetchone()        if row:            return dict(row)        return None# =============================================================================if __name__ == "__main__":    registry = AgentRegistry()    registry.register(        agent_uuid="AG001",        agent_name="CODEX",        role="SOFTWARE_ENGINEER",        capabilities=[            "python",            "fastapi",            "sqlite",            "refactoring"        ],        permissions=[            "READ",            "WRITE",            "EXECUTE"        ]    )    registry.register(        agent_uuid="AG002",        agent_name="OPENHANDS",        role="AUTONOMOUS_EXECUTOR",        capabilities=[            "terminal",            "git",            "tests",            "automation"        ],        permissions=[            "READ",            "WRITE",            "EXECUTE"        ]    )    registry.register(        agent_uuid="AG003",        agent_name="CHATGPT",        role="ARCHITECT",        capabilities=[            "architecture",            "planning",            "analysis"        ],        permissions=[            "READ"        ]    )    for agent in registry.list_agents():        print(agent)